def read_json_file(path: Path, fallback: dict) -> dict:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return fallback


def write_json_file(path: Path, payload: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp_path = path.with_suffix(path.suffix + ".tmp")
    tmp_path.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
    tmp_path.replace(path)


def normalize_current_time_skill_settings(payload: dict | None) -> dict:
    payload = payload if isinstance(payload, dict) else {}
    raw_sources = payload.get("sources")
    if not isinstance(raw_sources, list):
        raw_sources = DEFAULT_CURRENT_TIME_SKILL_SETTINGS["sources"]
    sources = [
        source
        for source in CURRENT_TIME_SKILL_SOURCES
        if source in {str(item or "").strip().lower() for item in raw_sources}
    ]
    if not sources:
        sources = list(CURRENT_TIME_SKILL_SOURCES)
    last_published_at = finite_float(payload.get("last_published_at")) or 0.0
    last_by_source = payload.get("last_publish_by_source")
    next_by_source = payload.get("next_publish_by_source")
    next_by_source = dict(next_by_source) if isinstance(next_by_source, dict) else {}
    next_by_source = {
        source: float(next_at)
        for source, raw_next in next_by_source.items()
        if source in sources and (next_at := finite_float(raw_next)) is not None and next_at > 0
    }
    next_published_at = min(next_by_source.values(), default=0.0)
    return {
        "enabled": bool(payload.get("enabled", DEFAULT_CURRENT_TIME_SKILL_SETTINGS["enabled"])),
        "distribution": "uniform",
        "minimum_delay_seconds": 60.0,
        "maximum_delay_seconds": 300.0,
        "sources": sources,
        "last_published_at": last_published_at,
        "next_published_at": next_published_at,
        "last_timestamp": str(payload.get("last_timestamp") or ""),
        "last_publish_by_source": dict(last_by_source) if isinstance(last_by_source, dict) else {},
        "next_publish_by_source": next_by_source,
        "publish_count": max(0, int(finite_float(payload.get("publish_count")) or 0)),
        "updated_at": finite_float(payload.get("updated_at")) or time.time(),
    }


def read_current_time_skill_settings(args: argparse.Namespace) -> dict:
    path = Path(args.current_time_skill_settings_path)
    with CURRENT_TIME_SKILL_SETTINGS_LOCK:
        return normalize_current_time_skill_settings(
            read_json_file(path, DEFAULT_CURRENT_TIME_SKILL_SETTINGS)
        )


def write_current_time_skill_settings(args: argparse.Namespace, payload: dict) -> dict:
    normalized = normalize_current_time_skill_settings(payload)
    normalized["updated_at"] = time.time()
    with CURRENT_TIME_SKILL_SETTINGS_LOCK:
        write_json_file(Path(args.current_time_skill_settings_path), normalized)
    return normalized


def draw_current_time_skill_next_at(now: float | None = None) -> float:
    drawn_at = time.time() if now is None else float(now)
    return drawn_at + random.uniform(60.0, 300.0)


def current_time_routable_sources(sources: list[str] | tuple[str, ...]) -> list[str]:
    requested = [source for source in sources if source in CURRENT_TIME_SKILL_SOURCES]
    pid_paths = {
        source: PROJECT_ROOT / f"webcam-voicechat-{source}.pid"
        for source in CURRENT_TIME_SKILL_SOURCES
    }
    if not any(path.exists() for path in pid_paths.values()):
        return requested
    running = []
    for source in requested:
        try:
            pid = int(pid_paths[source].read_text(encoding="utf-8").strip())
            os.kill(pid, 0)
        except (OSError, ValueError):
            continue
        running.append(source)
    return running


def _merge_service_turn(items: object, source: str, turn: dict) -> list[dict]:
    existing = []
    for item in items if isinstance(items, list) else []:
        if not isinstance(item, dict):
            continue
        normalized = dict(item)
        if str(normalized.get("skill") or "") == "current_time":
            normalized.update({
                "role": "user",
                "source": source,
                "lane_source": source,
                "service": "time-service",
                "label": "Time service",
                "input_label": "Time service",
                "raw_notification": True,
            })
        existing.append(normalized)
    existing.append({**turn, "lane_source": source})
    return existing[-400:]


def publish_current_time_skill(
    args: argparse.Namespace,
    settings: dict | None = None,
    sources: list[str] | tuple[str, ...] | None = None,
) -> dict:
    """Queue selected lane events for Nemotron, then redraw each lane's next time."""
    settings = normalize_current_time_skill_settings(settings or read_current_time_skill_settings(args))
    requested_sources = {
        str(source or "").strip().lower()
        for source in (sources if sources is not None else settings["sources"])
    }
    target_sources = current_time_routable_sources([
        source for source in settings["sources"] if source in requested_sources
    ])
    now = time.time()
    timestamp = datetime.fromtimestamp(now).astimezone().isoformat(timespec="seconds")
    published_sources: list[str] = []
    for source in target_sources:
        request = append_manual_voicechat_input(
            args,
            source,
            f"Current timestamp: {timestamp}",
            {
                "kind": "current_time_notification",
                "trigger": "current_time_service",
                "input_label": "Time service",
                "skill": "current_time",
                "timestamp": timestamp,
            },
        )
        if not request.get("suppressed"):
            published_sources.append(source)
    last_by_source = dict(settings.get("last_publish_by_source") or {})
    last_by_source.update({source: now for source in published_sources})
    next_by_source = dict(settings.get("next_publish_by_source") or {})
    next_by_source.update({source: draw_current_time_skill_next_at(now) for source in published_sources})
    return write_current_time_skill_settings(args, {
        **settings,
        "last_published_at": now,
        "last_timestamp": timestamp,
        "last_publish_by_source": last_by_source,
        "next_publish_by_source": next_by_source,
        "publish_count": int(settings.get("publish_count") or 0) + 1,
    })


def current_time_skill_publisher(args: argparse.Namespace, stop: threading.Event) -> None:
    while not stop.is_set():
        try:
            settings = read_current_time_skill_settings(args)
            if settings["enabled"]:
                now = time.time()
                routable_sources = current_time_routable_sources(settings["sources"])
                prune_unroutable_current_time_requests(args, set(routable_sources))
                next_by_source = dict(settings.get("next_publish_by_source") or {})
                unscheduled = [source for source in routable_sources if not float(next_by_source.get(source) or 0)]
                if unscheduled:
                    next_by_source.update({source: draw_current_time_skill_next_at(now) for source in unscheduled})
                    settings = write_current_time_skill_settings(args, {
                        **settings,
                        "next_publish_by_source": next_by_source,
                    })
                due_sources = [
                    source
                    for source in routable_sources
                    if 0 < float(settings["next_publish_by_source"].get(source) or 0) <= now
                ]
                if due_sources:
                    publish_current_time_skill(args, settings, due_sources)
        except Exception as exc:  # pragma: no cover - operational guardrail
            sys.stderr.write(f"Current Time skill publisher failed: {exc}\n")
        stop.wait(1.0)


def publish_service_input_to_lane_thread(
    args: argparse.Namespace,
    source: str,
    service_label: str,
    text: str,
    request: dict | None = None,
) -> dict:
    """Persist a raw service input before any queueing, suppression, or model work."""
    response_value = str(getattr(args, "voicechat_response_path", "") or "").strip()
    if not response_value:
        return {}
    source_key = str(source or "").strip().lower()
    if source_key not in CURRENT_TIME_SKILL_SOURCES:
        return {}
    clean_text = " ".join(str(text or "").split())
    if not clean_text:
        return {}
    request = request if isinstance(request, dict) else {}
    now = finite_float(request.get("created_at") or request.get("updated_at")) or time.time()
    label = " ".join(str(service_label or "Service").split())[:80] or "Service"
    response_path = Path(response_value)
    history_path = voicechat_history_path(response_path)
    response_path.parent.mkdir(parents=True, exist_ok=True)
    lock_path = response_path.with_suffix(response_path.suffix + ".lock")
    turn = {
        "role": "user",
        "source": source_key,
        "lane_source": source_key,
        "text": clean_text,
        "status": "complete",
        "phase": str(request.get("kind") or request.get("trigger") or "service_input"),
        "service": re.sub(r"[^a-z0-9]+", "-", label.lower()).strip("-") or "service",
        "label": label,
        "input_label": label,
        "raw_notification": True,
        "notification_id": str(request.get("id") or f"service-{time.time_ns()}"),
        "trigger": str(request.get("trigger") or ""),
        "updated_at": now,
    }
    if request.get("skill"):
        turn["skill"] = str(request["skill"])
    if request.get("timestamp"):
        turn["timestamp"] = str(request["timestamp"])
    attachments = request.get("input_attachments") or request.get("attachments")
    if isinstance(attachments, list) and attachments:
        turn["attachments"] = attachments[:4]
    deepstream_event = request.get("deepstream_event")
    if isinstance(deepstream_event, dict) and deepstream_event:
        turn["service_payload"] = deepstream_event
    with lock_path.open("w", encoding="utf-8") as lock_file:
        fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX)
        try:
            response = read_json_file(response_path, {})
            history = read_json_file(history_path, {})
            response_by_source = response.get("conversation_by_source")
            response_by_source = dict(response_by_source) if isinstance(response_by_source, dict) else {}
            history_by_source = history.get("conversation_by_source")
            history_by_source = dict(history_by_source) if isinstance(history_by_source, dict) else {}
            base = history_by_source.get(source_key) or response_by_source.get(source_key) or []
            conversation = _merge_service_turn(base, source_key, turn)
            history_by_source[source_key] = conversation
            response_by_source[source_key] = conversation
            sources_state = response.get("sources")
            sources_state = dict(sources_state) if isinstance(sources_state, dict) else {}
            source_state = sources_state.get(source_key)
            source_state = dict(source_state) if isinstance(source_state, dict) else {}
            source_state.update({"input_source": source_key, "conversation": conversation})
            sources_state[source_key] = source_state
            response.update({
                "conversation_by_source": response_by_source,
                "sources": sources_state,
                "updated_at": max(float(response.get("updated_at") or 0), now),
            })
            history.update({
                "status": "ok",
                "conversation_by_source": history_by_source,
                "source_count": len(history_by_source),
                "updated_at": max(float(history.get("updated_at") or 0), now),
            })
            write_json_file(response_path, response)
            write_json_file(history_path, history)
        finally:
            fcntl.flock(lock_file.fileno(), fcntl.LOCK_UN)
    return turn


def normalize_nemotron_system_prompt(value: object) -> str:
    if isinstance(value, dict):
        value = value.get("system_prompt", DEFAULT_NEMOTRON_SYSTEM_PROMPT)
    return str(value or "")[:3000]


def nemotron_prompt_lane(source: str) -> str:
    return "wifi" if str(source or "").strip().lower() == "wifi" else "server"


def nemotron_system_prompt_path(args: argparse.Namespace, source: str = "server") -> Path:
    source = str(source or "server").strip().lower()
    if source not in {"server", "wifi"}:
        raise ValueError(f"Unsupported system prompt lane: {source}")
    explicit = getattr(args, f"nemotron_{source}_system_prompt_path", "")
    legacy = getattr(args, "nemotron_system_prompt_path", "")
    return Path(explicit or legacy or PROJECT_ROOT / f"webcam-nemotron-{source}-system-prompt.json")


def read_nemotron_system_prompt(args: argparse.Namespace, source: str = "server") -> str:
    path = nemotron_system_prompt_path(args, source)
    return normalize_nemotron_system_prompt(
        read_json_file(path, {"system_prompt": DEFAULT_NEMOTRON_SYSTEM_PROMPT})
    )


def write_nemotron_system_prompt(args: argparse.Namespace, source: str, value: object) -> dict:
    path = nemotron_system_prompt_path(args, source)
    stored_payload = {
        "source": source,
        "system_prompt": normalize_nemotron_system_prompt(value),
        "updated_at": time.time(),
    }
    write_json_file(path, stored_payload)
    return {**stored_payload, "config_file": str(path.resolve())}


def pause_focus_for_manual_ptz(command_path: Path, source: str, action: str,
                               duration_ms: int = 0, now: float | None = None,
                               settle_seconds: float = 0.75) -> dict:
    """Yield an active autofocus request to manual PTZ without cancelling it."""
    timestamp = time.time() if now is None else float(now)
    lock_path = command_path.with_suffix(command_path.suffix + ".lock")
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    with lock_path.open("a+", encoding="utf-8") as lock_file:
        fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX)
        command = read_json_file(command_path, {})
        if not command.get("enabled") or str(command.get("source") or "wifi").strip().lower() != source:
            return command
        pause_started_at = float(command.get("manual_ptz_pause_started_at") or 0.0)
        pause_until = float(command.get("manual_ptz_pause_until") or 0.0)
        paused_seconds = max(0.0, float(command.get("manual_ptz_paused_seconds") or 0.0))
        pause_active = bool(command.get("manual_ptz_active"))
        expires_at = float(command.get("expires_at") or 0.0)
        pause_in_progress = bool(
            pause_started_at > 0.0 and (pause_active or timestamp < pause_until)
        )
        if pause_started_at > 0.0 and not pause_active and pause_until > pause_started_at and timestamp >= pause_until:
            paused_seconds += pause_until - pause_started_at
            pause_started_at = 0.0
            pause_until = 0.0
            pause_in_progress = False
        if not pause_in_progress:
            pause_started_at = timestamp
        if action == "start":
            updated = {
                **command,
                "manual_ptz_active": True,
                "manual_ptz_pause_started_at": pause_started_at,
                "manual_ptz_pause_until": 0.0,
                "manual_ptz_paused_seconds": paused_seconds,
                "manual_ptz_updated_at": timestamp,
            }
        else:
            new_pause_until = timestamp + max(0.0, float(settle_seconds))
            if action == "pulse":
                new_pause_until += max(0, int(duration_ms)) / 1000.0
            if pause_active:
                deadline_extension = max(0.0, new_pause_until - pause_started_at)
            else:
                deadline_extension = max(0.0, new_pause_until - max(timestamp, pause_until))
            pause_until = max(pause_until, new_pause_until)
            updated = {
                **command,
                "manual_ptz_active": False,
                "manual_ptz_pause_started_at": pause_started_at,
                "manual_ptz_pause_until": pause_until,
                "manual_ptz_paused_seconds": paused_seconds,
                "manual_ptz_updated_at": timestamp,
                **({"expires_at": expires_at + deadline_extension} if expires_at > 0 else {}),
            }
        write_json_file(command_path, updated)
        return updated


def focus_reticle_visible(state: dict, source: str, now: float | None = None) -> bool:
    if str(state.get("source") or "").strip().lower() != str(source or "").strip().lower():
        return False
    if bool(state.get("enabled")):
        return True
    status = str(state.get("status") or "").strip().lower()
    if status not in {"complete", "failed", "timed_out", "error"}:
        return False
    updated_at = finite_float(state.get("updated_at")) or 0.0
    return 0.0 <= float(now if now is not None else time.time()) - updated_at <= 4.0


def focus_navigation_lines(state: dict) -> list[str]:
    try:
        step = max(0, int(state.get("pulse_count") or 0))
    except (TypeError, ValueError):
        step = 0
    try:
        maximum = max(1, int(state.get("max_steps") or 100))
    except (TypeError, ValueError):
        maximum = 100
    logical = str(
        state.get("pending_pulse_action_direction")
        or state.get("direction")
        or state.get("next_direction")
        or "hold"
    ).strip().lower()
    command = str(state.get("pending_pulse_direction") or state.get("hardware_direction") or "").strip().lower()
    arrows = {"left": "<-", "right": "->", "up": "^", "down": "v", "hold": "o"}
    offset = state.get("offset") if isinstance(state.get("offset"), dict) else {}
    dx = finite_float(offset.get("x")) or 0.0
    dy = finite_float(offset.get("y")) or 0.0
    distance = finite_float(state.get("distance_to_center"))
    if distance is None:
        distance = math.hypot(dx, dy)
    try:
        duration = max(0, int(state.get("pending_pulse_duration_ms") or state.get("duration_ms") or 0))
    except (TypeError, ValueError):
        duration = 0
    backend = str(state.get("pending_pulse_backend") or state.get("backend") or "").strip().lower()
    runtime = finite_float(state.get("auto_centering_runtime_seconds"))
    if runtime is None:
        history = state.get("history") if isinstance(state.get("history"), list) else []
        source = str(state.get("source") or "").strip().lower()
        for item in reversed(history):
            if not isinstance(item, dict) or str(item.get("source") or "").strip().lower() != source:
                continue
            runtime = finite_float(item.get("runtime_seconds"))
            if runtime is not None:
                break
    command_note = f"  CMD {command.upper()}" if command and command != logical else ""
    pulse_note = f"  {duration}ms" if duration else ""
    backend_note = f"  {backend}" if backend else ""
    configured_models = state.get("focus_response_models") if isinstance(state.get("focus_response_models"), dict) else {}
    planning = state.get("gru_planning") if isinstance(state.get("gru_planning"), dict) else {}
    def model_label(axis: str) -> str:
        selected = str(configured_models.get(axis) or "linear").strip().lower()
        effective = str((planning.get(axis) or {}).get("model") or selected).strip().lower()
        if effective == "linear_fallback":
            return "GRU>LINEAR"
        return effective.upper()
    lines = [
        f"STEP {step}/{maximum}  {arrows.get(logical, 'o')} {logical.upper()}{command_note}",
        f"DX {dx:+.4f}  DY {dy:+.4f}  DIST {distance:.4f}",
        f"{str(state.get('status') or 'waiting').upper()}{pulse_note}{backend_note}",
        f"MODELS  LEFT/RIGHT: {model_label('x')}  UP/DOWN: {model_label('y')}",
        f"LAST RUN {runtime:.2f}s" if runtime is not None else "LAST RUN --",
    ]
    if str(state.get("target_recovery_mode") or "").strip().lower() == "backtracking":
        try:
            recovery_steps = max(0, int(state.get("target_recovery_steps") or 0))
        except (TypeError, ValueError):
            recovery_steps = 0
        try:
            history_depth = max(0, int(state.get("movement_history_depth") or 0))
        except (TypeError, ValueError):
            history_depth = 0
        lines.insert(0, f"!! OBJECT LOST - BACKTRACKING  REV {recovery_steps}  HIST {history_depth}")
    return lines


def draw_focus_navigation_hud(draw: ImageDraw.ImageDraw, image_width: int, state: dict, scale: int) -> None:
    lines = focus_navigation_lines(state)
    padding = max(4, scale * 3)
    line_gap = max(2, scale)
    boxes = [draw.textbbox((0, 0), line) for line in lines]
    line_heights = [max(8, box[3] - box[1]) for box in boxes]
    panel_width = min(image_width - 2, max(box[2] - box[0] for box in boxes) + padding * 2)
    panel_height = sum(line_heights) + line_gap * (len(lines) - 1) + padding * 2
    draw.rectangle((6, 6, 6 + panel_width, 6 + panel_height), fill=(7, 10, 14), outline=(115, 225, 255), width=max(1, scale))
    y = 6 + padding
    for index, (line, line_height) in enumerate(zip(lines, line_heights)):
        if line.startswith("!! OBJECT LOST"):
            color = (255, 105, 85)
        elif line.startswith("STEP "):
            color = (255, 208, 90)
        else:
            color = (220, 239, 248)
        draw.text((6 + padding, y), line, fill=color)
        y += line_height + line_gap


def draw_dashed_rectangle(draw: ImageDraw.ImageDraw, bounds: tuple[int, int, int, int], color: tuple[int, int, int], width: int, dash: int) -> None:
    left, top, right, bottom = bounds
    for start in range(left, right, dash * 2):
        draw.line((start, top, min(right, start + dash), top), fill=color, width=width)
        draw.line((start, bottom, min(right, start + dash), bottom), fill=color, width=width)
    for start in range(top, bottom, dash * 2):
        draw.line((left, start, left, min(bottom, start + dash)), fill=color, width=width)
        draw.line((right, start, right, min(bottom, start + dash)), fill=color, width=width)


def draw_focus_reticle_on_image(image: Image.Image, state: dict, source: str, now: float | None = None) -> bool:
    if not focus_reticle_visible(state, source, now):
        return False
    draw = ImageDraw.Draw(image)
    image_width, image_height = image.size
    scale = max(1, round(min(image_width, image_height) / 240))
    goal = state.get("goal_center") if isinstance(state.get("goal_center"), dict) else {}
    goal_x = max(0.0, min(1.0, finite_float(goal.get("x")) or 0.5))
    goal_y = max(0.0, min(1.0, finite_float(goal.get("y")) or 0.5))
    center_x = round(goal_x * image_width)
    center_y = round(goal_y * image_height)
    cyan = (115, 225, 255)
    amber = (255, 208, 90)
    radius = max(12, scale * 9)
    arm = max(20, scale * 15)
    draw.ellipse((center_x - radius, center_y - radius, center_x + radius, center_y + radius), outline=cyan, width=max(2, scale * 2))
    draw.line((center_x - arm, center_y, center_x + arm, center_y), fill=cyan, width=max(2, scale * 2))
    draw.line((center_x, center_y - arm, center_x, center_y + arm), fill=cyan, width=max(2, scale * 2))

    target = state.get("object_center") if isinstance(state.get("object_center"), dict) else None
    if target is None:
        draw_focus_navigation_hud(draw, image_width, state, scale)
        return True
    target_x = round(max(0.0, min(1.0, finite_float(target.get("x")) or 0.5)) * image_width)
    target_y = round(max(0.0, min(1.0, finite_float(target.get("y")) or 0.5)) * image_height)
    draw.line((center_x, center_y, target_x, target_y), fill=amber, width=max(1, scale))
    target_radius = max(14, scale * 10)
    target_arm = max(22, scale * 16)
    draw.ellipse((target_x - target_radius, target_y - target_radius, target_x + target_radius, target_y + target_radius), outline=amber, width=max(2, scale * 2))
    draw.line((target_x - target_arm, target_y, target_x + target_arm, target_y), fill=amber, width=max(2, scale * 2))
    draw.line((target_x, target_y - target_arm, target_x, target_y + target_arm), fill=amber, width=max(2, scale * 2))
    bbox = state.get("bbox") if isinstance(state.get("bbox"), list) else []
    frame_size = state.get("frame_size") if isinstance(state.get("frame_size"), list) else []
    if len(bbox) >= 4 and len(frame_size) >= 2:
        frame_width = finite_float(frame_size[0]) or 0.0
        frame_height = finite_float(frame_size[1]) or 0.0
        if frame_width > 0 and frame_height > 0:
            projected_width = max(1, round(float(bbox[2]) / frame_width * image_width))
            projected_height = max(1, round(float(bbox[3]) / frame_height * image_height))
            left = round(center_x - projected_width / 2)
            top = round(center_y - projected_height / 2)
            right = left + projected_width
            bottom = top + projected_height
            draw_dashed_rectangle(
                draw,
                (left, top, right, bottom),
                cyan,
                max(1, scale),
                max(4, scale * 4),
            )
    label = f"{state.get('target_label') or 'target'} · {state.get('status') or 'focusing'}"
    text_box = draw.textbbox((0, 0), label)
    text_width = text_box[2] - text_box[0] + 8
    text_height = text_box[3] - text_box[1] + 6
    label_x = max(0, min(image_width - text_width, target_x - text_width // 2))
    label_y = max(0, target_y - target_radius - text_height - 4)
    draw.rectangle((label_x, label_y, label_x + text_width, label_y + text_height), fill=(7, 10, 14), outline=amber, width=1)
    draw.text((label_x + 4, label_y + 3), label, fill=(255, 245, 214))
    draw_focus_navigation_hud(draw, image_width, state, scale)
    return True


def deepstream_notification_monitor(
    stop: threading.Event,
    endpoint_url: str,
    interval_seconds: float = 0.25,
    wake_socket_path: str = "",
) -> None:
    """Drive notifications on detector events, retaining polling as fallback."""
    interval = max(0.1, float(interval_seconds or 0.25))
    request = Request(endpoint_url, headers={"Cache-Control": "no-cache", "X-Internal-Monitor": "deepstream"})
    tls_context = ssl._create_unverified_context() if endpoint_url.lower().startswith("https://") else None
    wake_socket = None
    wake_path = Path(wake_socket_path) if str(wake_socket_path or "").strip() else None
    try:
        if wake_path is not None:
            wake_path.parent.mkdir(parents=True, exist_ok=True)
            wake_path.unlink(missing_ok=True)
            wake_socket = socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM)
            wake_socket.setblocking(False)
            wake_socket.bind(str(wake_path))
        while not stop.is_set():
            event_received = False
            if wake_socket is not None:
                readable, _, _ = select.select([wake_socket], [], [], interval)
                if readable:
                    event_received = True
                    try:
                        while wake_socket.recv(4096):
                            pass
                    except BlockingIOError:
                        pass
            else:
                stop.wait(interval)
            if stop.is_set():
                break
            try:
                with urlopen(request, timeout=max(1.0, interval * 4.0), context=tls_context) as response:
                    response.read(2 * 1024 * 1024)
            except Exception:
                pass
            if event_received:
                # Coalesce detector jitter while keeping event response near real time.
                stop.wait(0.08)
    finally:
        if wake_socket is not None:
            wake_socket.close()
        if wake_path is not None:
            wake_path.unlink(missing_ok=True)


IMAGE_DATA_DISPLAY_REDACTION = "[image data omitted]"
IMAGE_DATA_KEY_RE = re.compile(r"(^|_)(data_url|image_data_url|image_base64|base64)$|image_data|_base64$", re.I)
INLINE_IMAGE_DATA_RE = re.compile(r"data:image/[a-z0-9.+-]+;base64,[a-z0-9+/=]+", re.I)
VOICECHAT_UI_MAX_CONVERSATION_ITEMS = 400
VOICECHAT_UI_RESPONSE_CACHE: dict[tuple[str, tuple[int, int], tuple[int, int], tuple[int, int]], bytes] = {}
VOICECHAT_UI_RESPONSE_CACHE_LOCK = threading.Lock()


def file_cache_stamp(path: Path) -> tuple[int, int]:
    try:
        stat = path.stat()
    except OSError:
        return (0, 0)
    return (stat.st_mtime_ns, stat.st_size)


def key_looks_like_image_data(key: str) -> bool:
    return bool(IMAGE_DATA_KEY_RE.search(str(key or "")))


def strip_inline_image_data_for_ui(value, key: str = ""):
    if value is None:
        return value
    if isinstance(value, str):
        if key_looks_like_image_data(key) and value:
            return IMAGE_DATA_DISPLAY_REDACTION if value.startswith("data:image/") else value
        if "data:image/" in value:
            return INLINE_IMAGE_DATA_RE.sub(IMAGE_DATA_DISPLAY_REDACTION, value)
        return value
    if isinstance(value, list):
        return [strip_inline_image_data_for_ui(item, key) for item in value]
    if isinstance(value, dict):
        stripped = {}
        for child_key, child_value in value.items():
            child_key_text = str(child_key or "")
            if key_looks_like_image_data(child_key_text):
                stripped[child_key] = IMAGE_DATA_DISPLAY_REDACTION if child_value else child_value
            else:
                stripped[child_key] = strip_inline_image_data_for_ui(child_value, child_key_text)
        return stripped
    return value


def limit_conversation_items_for_ui(items: object) -> list[dict]:
    if not isinstance(items, list):
        return []
    cleaned = [item for item in items if isinstance(item, dict)]
    if len(cleaned) <= VOICECHAT_UI_MAX_CONVERSATION_ITEMS:
        return cleaned
    return cleaned[-VOICECHAT_UI_MAX_CONVERSATION_ITEMS:]


def limit_voicechat_payload_for_ui(payload: dict) -> dict:
    if not isinstance(payload, dict):
        return payload
    limited = dict(payload)
    conversation = limit_conversation_items_for_ui(limited.get("conversation"))
    if conversation:
        limited["conversation"] = conversation
        limited["conversation_omitted_count"] = max(
            0,
            len(payload.get("conversation") if isinstance(payload.get("conversation"), list) else []) - len(conversation),
        )

    by_source = limited.get("conversation_by_source")
    if isinstance(by_source, dict):
        limited_by_source = {}
        omitted_by_source = {}
        for source, items in by_source.items():
            limited_items = limit_conversation_items_for_ui(items)
            if limited_items:
                limited_by_source[source] = limited_items
                omitted = max(0, len(items if isinstance(items, list) else []) - len(limited_items))
                if omitted:
                    omitted_by_source[source] = omitted
        limited["conversation_by_source"] = limited_by_source
        if omitted_by_source:
            limited["conversation_omitted_by_source"] = omitted_by_source

    sources = limited.get("sources")
    if isinstance(sources, dict):
        limited_sources = {}
        for source, state in sources.items():
            if not isinstance(state, dict):
                limited_sources[source] = state
                continue
            state_copy = dict(state)
            state_conversation = limit_conversation_items_for_ui(state_copy.get("conversation"))
            if state_conversation:
                state_copy["conversation"] = state_conversation
            limited_sources[source] = state_copy
        limited["sources"] = limited_sources
    return limited


def pending_voicechat_manual_inputs_by_source(path: Path) -> dict[str, list[dict]]:
    data = read_json_file(path, {})
    pending = data.get("pending") if isinstance(data.get("pending"), list) else []
    by_source: dict[str, list[dict]] = {}
    for item in pending:
        if not isinstance(item, dict):
            continue
        source = str(item.get("source") or "").strip().lower()
        text = " ".join(str(item.get("text") or "").split())
        if source not in {"server", "wifi", "bulb", "browser"} or not text:
            continue
        entry = strip_inline_image_data_for_ui(
            {
                "id": item.get("id", ""),
                "source": source,
                "text": text,
                "status": "queued",
                "kind": item.get("kind", ""),
                "trigger": item.get("trigger", ""),
                "input_label": item.get("input_label") or (
                    "Live Stream Processor" if manual_voicechat_request_is_deepstream_event(item) else "Manual text"
                ),
                "attachments": item.get("input_attachments") or item.get("attachments") or [],
                "created_at": item.get("created_at", 0),
                "updated_at": item.get("updated_at", item.get("created_at", 0)),
            }
        )
        by_source.setdefault(source, []).append(entry)
    return by_source


def add_pending_voicechat_manual_inputs_for_ui(payload: dict, manual_input_path: Path) -> dict:
    pending_by_source = pending_voicechat_manual_inputs_by_source(manual_input_path)
    if not pending_by_source:
        return payload
    enriched = dict(payload)
    enriched["pending_manual_inputs_by_source"] = pending_by_source
    sources = dict(enriched.get("sources") if isinstance(enriched.get("sources"), dict) else {})
    for source, pending_items in pending_by_source.items():
        source_state = sources.get(source) if isinstance(sources.get(source), dict) else {}
        next_state = dict(source_state)
        next_state["input_source"] = next_state.get("input_source") or source
        next_state["pending_manual_inputs"] = pending_items
        sources[source] = next_state
    enriched["sources"] = sources
    return enriched


def normalize_service_attribution_for_ui(payload: dict) -> dict:
    """Repair legacy/service turns at the API boundary, including old worker output."""
    normalized = dict(payload) if isinstance(payload, dict) else {}

    def normalize_items(items: object, lane: str) -> object:
        if not isinstance(items, list):
            return items
        result = []
        for raw in items:
            if not isinstance(raw, dict):
                continue
            item = dict(raw)
            phase = str(item.get("phase") or "").strip().lower()
            trigger = str(item.get("trigger") or "").strip().lower()
            if str(item.get("skill") or "").strip().lower() == "current_time":
                item.update({
                    "role": "user",
                    "source": lane,
                    "lane_source": lane,
                    "service": "time-service",
                    "label": "Time service",
                    "input_label": "Time service",
                    "raw_notification": True,
                })
            elif (
                bool(item.get("raw_notification"))
                or phase == "deepstream_object_change"
                or trigger in {"deepstream_yolo_coco", "focus_object_acquired"}
            ):
                label = str(item.get("label") or item.get("input_label") or "Live Stream service")
                if label.strip().lower() == "live stream processor":
                    label = "Live Stream service"
                item.update({
                    "role": "user",
                    "source": lane,
                    "lane_source": lane,
                    "service": item.get("service") or "live-stream-service",
                    "label": label,
                    "input_label": label,
                    "raw_notification": True,
                })
            result.append(item)
        return result

    by_source = normalized.get("conversation_by_source")
    if isinstance(by_source, dict):
        normalized["conversation_by_source"] = {
            str(lane): normalize_items(items, str(lane))
            for lane, items in by_source.items()
        }
    sources = normalized.get("sources")
    if isinstance(sources, dict):
        next_sources = {}
        for lane, state in sources.items():
            if not isinstance(state, dict):
                next_sources[lane] = state
                continue
            next_state = dict(state)
            next_state["conversation"] = normalize_items(next_state.get("conversation"), str(lane))
            next_sources[lane] = next_state
        normalized["sources"] = next_sources
    top_lane = str(normalized.get("input_source") or "").strip().lower()
    if top_lane:
        normalized["conversation"] = normalize_items(normalized.get("conversation"), top_lane)
    return normalized


def voicechat_ui_response_body(response_path: Path, fallback: dict, manual_input_path: Path) -> bytes:
    history_path = voicechat_history_path(response_path)
    response_stamp = file_cache_stamp(response_path)
    history_stamp = file_cache_stamp(history_path)
    manual_stamp = file_cache_stamp(manual_input_path)
    cache_key = (str(response_path.resolve()), response_stamp, history_stamp, manual_stamp)
    with VOICECHAT_UI_RESPONSE_CACHE_LOCK:
        cached = VOICECHAT_UI_RESPONSE_CACHE.get(cache_key)
        if cached is not None:
            return cached

    if response_path.exists():
        payload = json.loads(response_path.read_text(encoding="utf-8"))
    else:
        payload = fallback
    payload = merge_voicechat_history_payload(payload, read_json_file(history_path, {}))
    payload = add_pending_voicechat_manual_inputs_for_ui(payload, manual_input_path)
    payload = normalize_service_attribution_for_ui(payload)
    payload = strip_inline_image_data_for_ui(payload)
    payload = limit_voicechat_payload_for_ui(payload)
    body = json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8")

    with VOICECHAT_UI_RESPONSE_CACHE_LOCK:
        VOICECHAT_UI_RESPONSE_CACHE.clear()
        VOICECHAT_UI_RESPONSE_CACHE[cache_key] = body
    return body


def voicechat_history_path(response_path: Path | str) -> Path:
    return Path(response_path).with_name("webcam-voicechat-history.json")


def clean_voicechat_conversation_items(items: object, limit: int | None = None) -> list[dict]:
    if not isinstance(items, list):
        return []
    cleaned = [item for item in items if isinstance(item, dict)]
    if limit is None or limit <= 0:
        return cleaned
    return cleaned[-limit:]


def voicechat_conversation_source(conversation: list[dict]) -> str:
    for item in conversation:
        if not isinstance(item, dict) or item.get("role") != "user":
            continue
        source = str(item.get("source") or "").strip().lower()
        if source:
            return source
    return ""


def voicechat_conversation_by_source_map(data: object, limit: int | None = None) -> dict[str, list[dict]]:
    conversations: dict[str, list[dict]] = {}
    if not isinstance(data, dict):
        return conversations
    max_items = limit * 2 if limit else None

    sources = data.get("sources")
    if isinstance(sources, dict):
        for source, state in sources.items():
            if not isinstance(state, dict):
                continue
            source_key = str(source or state.get("input_source") or "").strip().lower()
            if not source_key:
                continue
            clean_items = clean_voicechat_conversation_items(state.get("conversation"), max_items)
            if clean_items:
                conversations[source_key] = clean_items

    by_source = data.get("conversation_by_source")
    if isinstance(by_source, dict):
        for source, items in by_source.items():
            source_key = str(source or "").strip().lower()
            if not source_key:
                continue
            clean_items = clean_voicechat_conversation_items(items, max_items)
            if clean_items:
                conversations[source_key] = clean_items

    clean_items = clean_voicechat_conversation_items(data.get("conversation"), max_items)
    source_key = str(data.get("input_source") or voicechat_conversation_source(clean_items)).strip().lower()
    if source_key and clean_items:
        conversations[source_key] = clean_items
    return conversations


def merge_voicechat_history_payload(payload: dict, history: object) -> dict:
    merged = dict(payload) if isinstance(payload, dict) else {}
    by_source = voicechat_conversation_by_source_map(history)
    by_source.update(voicechat_conversation_by_source_map(merged))
    if not by_source:
        return merged

    merged["conversation_by_source"] = by_source
    source = str(merged.get("input_source") or "").strip().lower()
    if source and not clean_voicechat_conversation_items(merged.get("conversation")) and by_source.get(source):
        merged["conversation"] = by_source[source]

    sources = merged.get("sources")
    if isinstance(sources, dict):
        next_sources = dict(sources)
        for source_key, conversation in by_source.items():
            source_state = next_sources.get(source_key)
            if not isinstance(source_state, dict):
                source_state = {}
            enriched_state = dict(source_state)
            enriched_state["input_source"] = enriched_state.get("input_source") or source_key
            enriched_state["conversation"] = conversation
            next_sources[source_key] = enriched_state
        merged["sources"] = next_sources
    return merged


def clear_voicechat_history(response_path: Path | str, now: float, session_id: str, reason: str) -> None:
    write_json_file(
        voicechat_history_path(response_path),
        {
            "status": "cleared",
            "updated_at": now,
            "session_id": session_id,
            "reason": reason,
            "conversation_by_source": {},
        },
    )


manual_voicechat_input_lock = threading.Lock()


def manual_voicechat_request_is_deepstream_event(request: dict) -> bool:
    if not isinstance(request, dict):
        return False
    kind = str(request.get("kind") or "").strip().lower()
    trigger = str(request.get("trigger") or "").strip().lower()
    return (
        kind == "deepstream_object_change"
        or trigger == "deepstream_yolo_coco"
        or isinstance(request.get("deepstream_event"), dict)
    )


def manual_voicechat_deepstream_in_flight(data: dict, now: float | None = None) -> dict:
    if not isinstance(data, dict):
        return {}
    checked_at = float(now if now is not None else time.time())
    active_requests = data.get("active_requests") if isinstance(data.get("active_requests"), dict) else {}
    for active in active_requests.values():
        if not isinstance(active, dict) or not manual_voicechat_request_is_deepstream_event(active):
            continue
        started_at = finite_float(active.get("started_at") or active.get("updated_at") or active.get("created_at")) or checked_at
        if checked_at - started_at > DEEPSTREAM_NOTIFICATION_BUSY_TIMEOUT_SECONDS:
            continue
        try:
            worker_pid = int(active.get("worker_pid") or 0)
        except (TypeError, ValueError):
            worker_pid = 0
        if worker_pid > 0:
            try:
                os.kill(worker_pid, 0)
            except OSError:
                continue
        return {"state": "active", "request": active}
    pending = data.get("pending") if isinstance(data.get("pending"), list) else []
    for request in pending:
        if not isinstance(request, dict) or not manual_voicechat_request_is_deepstream_event(request):
            continue
        created_at = finite_float(request.get("created_at") or request.get("updated_at")) or checked_at
        if checked_at - created_at <= DEEPSTREAM_NOTIFICATION_BUSY_TIMEOUT_SECONDS:
            return {"state": "pending", "request": request}
    recently_completed = (
        data.get("recently_completed_requests")
        if isinstance(data.get("recently_completed_requests"), dict)
        else {}
    )
    for completed in recently_completed.values():
        if not isinstance(completed, dict) or not manual_voicechat_request_is_deepstream_event(completed):
            continue
        completed_at = finite_float(completed.get("completed_at") or completed.get("updated_at")) or 0.0
        if 0.0 <= checked_at - completed_at <= DEEPSTREAM_NOTIFICATION_POST_COMPLETION_QUIET_SECONDS:
            return {"state": "post-completion quiet period", "request": completed}
    return {}


def read_manual_voicechat_deepstream_in_flight(path: Path | str, now: float | None = None) -> dict:
    input_path = Path(path)
    lock_path = input_path.with_suffix(input_path.suffix + ".lock")
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    with lock_path.open("w", encoding="utf-8") as lock_file:
        fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX)
        try:
            return manual_voicechat_deepstream_in_flight(read_json_file(input_path, {}), now)
        finally:
            fcntl.flock(lock_file.fileno(), fcntl.LOCK_UN)


def trim_manual_voicechat_pending(pending: list[dict]) -> list[dict]:
    clean_pending = [item for item in pending if isinstance(item, dict)]
    deepstream_indices = [
        index
        for index, item in enumerate(clean_pending)
        if manual_voicechat_request_is_deepstream_event(item)
    ]
    keep_indices = {
        index
        for index, item in enumerate(clean_pending)
        if not manual_voicechat_request_is_deepstream_event(item)
    }
    keep_indices.update(deepstream_indices[-VOICECHAT_AUTOMATED_DEEPSTREAM_PENDING_LIMIT:])
    if len(keep_indices) > VOICECHAT_MANUAL_PENDING_LIMIT:
        for index in sorted(keep_indices):
            if len(keep_indices) <= VOICECHAT_MANUAL_PENDING_LIMIT:
                break
            if manual_voicechat_request_is_deepstream_event(clean_pending[index]):
                keep_indices.remove(index)
    if len(keep_indices) > VOICECHAT_MANUAL_PENDING_LIMIT:
        for index in sorted(keep_indices):
            if len(keep_indices) <= VOICECHAT_MANUAL_PENDING_LIMIT:
                break
            keep_indices.remove(index)
    return [
        item
        for index, item in enumerate(clean_pending)
        if index in keep_indices
    ]


def clean_manual_voicechat_extra(extra: dict | None) -> dict:
    if not isinstance(extra, dict):
        return {}
    allowed = {
        "kind",
        "trigger",
        "skip_tool_planning",
        "input_label",
        "input_attachments",
        "attachments",
        "tool_results",
        "tool_summary",
        "focus_target",
        "focus_request",
        "deepstream_event",
        "system_prompt",
        "skill",
        "timestamp",
    }
    cleaned = {key: extra[key] for key in allowed if key in extra}
    for key in ("input_attachments", "attachments", "tool_results"):
        if key in cleaned and not isinstance(cleaned[key], list):
            cleaned.pop(key, None)
    if "deepstream_event" in cleaned and not isinstance(cleaned["deepstream_event"], dict):
        cleaned.pop("deepstream_event", None)
    if "focus_target" in cleaned and not isinstance(cleaned["focus_target"], dict):
        cleaned.pop("focus_target", None)
    if "focus_request" in cleaned and not isinstance(cleaned["focus_request"], dict):
        cleaned.pop("focus_request", None)
    if "system_prompt" in cleaned:
        system_prompt = str(cleaned.get("system_prompt") or "")[:3000]
        if system_prompt:
            cleaned["system_prompt"] = system_prompt
        else:
            cleaned.pop("system_prompt", None)
    return cleaned


def append_manual_voicechat_input(
    args: argparse.Namespace,
    source: str,
    text: str,
    extra: dict | None = None,
    queue_path: str | Path | None = None,
) -> dict:
    clean_source = str(source or "").strip().lower()
    if clean_source not in {"server", "wifi", "bulb", "browser"}:
        raise ValueError("source must be server, wifi, bulb, or browser")
    clean_text = " ".join(str(text or "").split())
    if not clean_text:
        raise ValueError("manual input text is empty")
    if len(clean_text) > 4000:
        clean_text = clean_text[:4000].rstrip()
    now = time.time()
    request = {
        "id": f"manual-{int(now * 1000)}-{clean_source}",
        "source": clean_source,
        "text": clean_text,
        "preempt_audio": True,
        "created_at": now,
        "updated_at": now,
    }
    request.update(clean_manual_voicechat_extra(extra))
    raw_input_label = " ".join(str(request.get("input_label") or "").split())
    service_label = raw_input_label
    if service_label.lower() == "live stream processor":
        service_label = "Live Stream service"
    if not service_label and manual_voicechat_request_is_deepstream_event(request):
        service_label = "Live Stream service"
    if (
        service_label
        and service_label.lower() not in {"manual text", "human text"}
        and str(request.get("kind") or "") != "current_time_notification"
    ):
        publish_service_input_to_lane_thread(args, clean_source, service_label, clean_text, request)
    path = Path(queue_path or args.voicechat_manual_input_path)
    with manual_voicechat_input_lock:
        lock_path = path.with_suffix(path.suffix + ".lock")
        lock_path.parent.mkdir(parents=True, exist_ok=True)
        with lock_path.open("w", encoding="utf-8") as lock_file:
            fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX)
            try:
                data = read_json_file(path, {})
                pending = data.get("pending") if isinstance(data.get("pending"), list) else []
                if manual_voicechat_request_is_deepstream_event(request):
                    in_flight = manual_voicechat_deepstream_in_flight(data, now)
                    if in_flight:
                        existing = in_flight.get("request") if isinstance(in_flight.get("request"), dict) else {}
                        return {
                            **request,
                            "suppressed": True,
                            "suppressed_reason": f"deepstream notification already {in_flight.get('state', 'in flight')}",
                            "existing_request_id": existing.get("id", ""),
                        }
                pending.append(request)
                pending = trim_manual_voicechat_pending(pending)
                payload = {
                    "status": "pending",
                    "updated_at": now,
                    "latest_request_id": request["id"],
                    "latest_consumed_id": data.get("latest_consumed_id", ""),
                    "active_requests": data.get("active_requests", {}),
                    "recently_completed_requests": data.get("recently_completed_requests", {}),
                    "pending": pending,
                }
                write_json_file(path, payload)
            finally:
                fcntl.flock(lock_file.fileno(), fcntl.LOCK_UN)
    return request


def prune_unroutable_current_time_requests(args: argparse.Namespace, routable_sources: set[str]) -> int:
    path = Path(args.voicechat_manual_input_path)
    if not path.exists():
        return 0
    lock_path = path.with_suffix(path.suffix + ".lock")
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    with lock_path.open("w", encoding="utf-8") as lock_file:
        fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX)
        try:
            data = read_json_file(path, {})
            pending = data.get("pending") if isinstance(data.get("pending"), list) else []
            retained = [
                item
                for item in pending
                if not (
                    isinstance(item, dict)
                    and str(item.get("skill") or "") == "current_time"
                    and str(item.get("source") or "").strip().lower() not in routable_sources
                )
            ]
            removed = len(pending) - len(retained)
            if removed:
                write_json_file(path, {
                    **data,
                    "status": "pending" if retained else "idle",
                    "pending": retained,
                    "updated_at": time.time(),
                })
            return removed
        finally:
            fcntl.flock(lock_file.fileno(), fcntl.LOCK_UN)


def deepstream_object_label(item: dict) -> str:
    return str(
        item.get("label")
        or item.get("class")
        or item.get("class_name")
        or item.get("name")
        or (f"class {item.get('class_id')}" if item.get("class_id") is not None else "")
        or "object"
    ).strip()


def deepstream_object_probability(item: dict) -> float:
    try:
        raw = float(item.get("confidence", item.get("score", item.get("probability", 0.0))))
    except (TypeError, ValueError):
        return 0.0
    if raw > 1.0:
        raw /= 100.0
    return max(0.0, min(1.0, raw))


def deepstream_object_count(item: dict) -> int:
    try:
        count = int(round(float(item.get("count", item.get("instances", 1)))))
    except (TypeError, ValueError):
        count = 1
    return max(1, count)


def deepstream_objects_from_payload(payload: dict) -> list[dict]:
    candidates = [payload.get("objects"), payload.get("detections"), payload.get("detected_objects")]
    latest_frame = payload.get("latest_frame") if isinstance(payload.get("latest_frame"), dict) else {}
    candidates.extend([latest_frame.get("objects"), latest_frame.get("detections")])
    for value in candidates:
        if isinstance(value, list):
            return [item for item in value if isinstance(item, dict)]
    return []


def deepstream_filter_objects_by_confidence(objects: list[dict], minimum_probability: float) -> list[dict]:
    try:
        threshold = float(minimum_probability)
    except (TypeError, ValueError):
        threshold = DEFAULT_DEEPSTREAM_SETTINGS["minimum_object_confidence_percent"] / 100.0
    threshold = max(0.0, min(1.0, threshold))
    return [
        item
        for item in objects
        if isinstance(item, dict) and deepstream_object_probability(item) >= threshold
    ]


def deepstream_total_object_count(objects: list[dict]) -> int:
    return sum(deepstream_object_count(item) for item in objects if isinstance(item, dict))


def deepstream_filter_payload_objects(payload: dict, settings: dict | None) -> dict:
    if not isinstance(payload, dict):
        return {}
    normalized_settings = normalize_deepstream_settings(settings)
    minimum_probability = float(
        normalized_settings.get(
            "minimum_object_confidence_threshold",
            DEFAULT_DEEPSTREAM_SETTINGS["minimum_object_confidence_percent"] / 100.0,
        )
    )
    minimum_percent = float(
        normalized_settings.get(
            "minimum_object_confidence_percent",
            DEFAULT_DEEPSTREAM_SETTINGS["minimum_object_confidence_percent"],
        )
    )
    updated = dict(payload)
    raw_objects = deepstream_objects_from_payload(updated)
    filtered_objects = deepstream_filter_objects_by_confidence(raw_objects, minimum_probability)

    found_top_level_list = False
    for key in ("objects", "detections", "detected_objects"):
        value = updated.get(key)
        if isinstance(value, list):
            found_top_level_list = True
            updated[key] = deepstream_filter_objects_by_confidence(value, minimum_probability)

    latest_frame = updated.get("latest_frame")
    if isinstance(latest_frame, dict):
        latest = dict(latest_frame)
        for key in ("objects", "detections", "detected_objects"):
            value = latest.get(key)
            if isinstance(value, list):
                latest[key] = deepstream_filter_objects_by_confidence(value, minimum_probability)
        updated["latest_frame"] = latest
    elif raw_objects and not found_top_level_list:
        updated["objects"] = filtered_objects

    visible_objects = deepstream_objects_from_payload(updated)
    updated["object_count"] = deepstream_total_object_count(visible_objects)
    updated["raw_object_count"] = deepstream_total_object_count(raw_objects)
    updated["filtered_object_count"] = deepstream_total_object_count(visible_objects)
    updated["minimum_object_confidence_percent"] = minimum_percent
    updated["minimum_object_confidence_threshold"] = minimum_probability
    if raw_objects and not visible_objects:
        updated["message"] = (
            f"Live Stream Processor filtered {deepstream_total_object_count(raw_objects)} "
            f"object(s) below {minimum_percent:g}% confidence."
        )
    return updated


def deepstream_object_monitor_summary(objects: list[dict]) -> dict:
    by_label: dict[str, list[float]] = {}
    details: list[dict] = []
    for item in objects:
        label = deepstream_object_label(item)
        if not label:
            continue
        probability = deepstream_object_probability(item)
        count = deepstream_object_count(item)
        for _ in range(count):
            by_label.setdefault(label, []).append(probability)
        details.append(
            {
                "label": label,
                "probability": probability,
                "confidence": probability,
                "class_id": item.get("class_id"),
                "bbox": item.get("bbox") or item.get("box") or item.get("rect"),
                "frame_width": item.get("frame_width") or item.get("image_width"),
                "frame_height": item.get("frame_height") or item.get("image_height"),
            }
        )
    probabilities = {label: sorted(values, reverse=True) for label, values in sorted(by_label.items())}
    counts = {label: len(values) for label, values in probabilities.items()}
    signature = json.dumps(
        {
            "counts": counts,
            "probabilities": {
                label: [round(value, 3) for value in values]
                for label, values in probabilities.items()
            },
        },
        sort_keys=True,
    )
    return {
        "counts": counts,
        "probabilities": probabilities,
        "objects": details,
        "signature": signature,
    }


def deepstream_object_crop_box(
    item: dict,
    image_width: int,
    image_height: int,
    padding_ratio: float = 0.08,
) -> tuple[int, int, int, int] | None:
    bbox = item.get("bbox") or item.get("box") or item.get("rect")
    if not isinstance(bbox, list) or len(bbox) < 4 or image_width <= 0 or image_height <= 0:
        return None
    try:
        left, top, width, height = (float(value) for value in bbox[:4])
        frame_width = float(item.get("frame_width") or item.get("image_width") or image_width)
        frame_height = float(item.get("frame_height") or item.get("image_height") or image_height)
    except (TypeError, ValueError):
        return None
    if frame_width <= 0 or frame_height <= 0 or width <= 0 or height <= 0:
        return None
    x1 = left / frame_width * image_width
    y1 = top / frame_height * image_height
    x2 = (left + width) / frame_width * image_width
    y2 = (top + height) / frame_height * image_height
    padding_ratio = max(0.0, float(padding_ratio))
    padding = max(4.0, max(x2 - x1, y2 - y1) * padding_ratio) if padding_ratio else 0.0
    crop = (
        max(0, int(math.floor(x1 - padding))),
        max(0, int(math.floor(y1 - padding))),
        min(image_width, int(math.ceil(x2 + padding))),
        min(image_height, int(math.ceil(y2 + padding))),
    )
    if crop[2] <= crop[0] or crop[3] <= crop[1]:
        return None
    return crop


def deepstream_monitor_change(previous: dict, current: dict, probability_change_threshold: float = DEEPSTREAM_PROBABILITY_CHANGE_THRESHOLD) -> tuple[bool, list[str]]:
    if not previous.get("initialized"):
        return False, []
    try:
        threshold = float(probability_change_threshold)
    except (TypeError, ValueError):
        threshold = DEEPSTREAM_PROBABILITY_CHANGE_THRESHOLD
    threshold = max(0.0, min(1.0, threshold))
    reasons: list[str] = []
    previous_counts = previous.get("counts") if isinstance(previous.get("counts"), dict) else {}
    current_counts = current.get("counts") if isinstance(current.get("counts"), dict) else {}
    if previous_counts != current_counts:
        added = sorted(set(current_counts) - set(previous_counts))
        removed = sorted(set(previous_counts) - set(current_counts))
        changed = sorted(
            label for label in set(previous_counts) & set(current_counts)
            if previous_counts.get(label) != current_counts.get(label)
        )
        if added:
            reasons.append("new: " + ", ".join(added))
        if removed:
            reasons.append("gone: " + ", ".join(removed))
        if changed:
            reasons.append(
                "count: "
                + ", ".join(f"{label} {previous_counts.get(label)}->{current_counts.get(label)}" for label in changed)
            )
    previous_probs = previous.get("probabilities") if isinstance(previous.get("probabilities"), dict) else {}
    current_probs = current.get("probabilities") if isinstance(current.get("probabilities"), dict) else {}
    for label in sorted(set(previous_probs) & set(current_probs)):
        old_values = [float(value) for value in previous_probs.get(label, [])]
        new_values = [float(value) for value in current_probs.get(label, [])]
        for index, (old_value, new_value) in enumerate(zip(old_values, new_values), start=1):
            delta = abs(new_value - old_value)
            if delta >= threshold:
                suffix = f" #{index}" if len(new_values) > 1 else ""
                reasons.append(f"{label}{suffix} {old_value * 100:.0f}%->{new_value * 100:.0f}%")
    return bool(reasons), reasons


def deepstream_objects_prompt_lines(objects: list[dict]) -> list[str]:
    if not objects:
        return ["- no COCO objects currently detected"]
    lines = []
    for item in sorted(objects, key=lambda value: (deepstream_object_label(value), -deepstream_object_probability(value))):
        label = deepstream_object_label(item)
        probability = deepstream_object_probability(item)
        count = deepstream_object_count(item)
        count_text = f" x{count}" if count > 1 else ""
        lines.append(f"- {label}{count_text}: {probability * 100:.0f}%")
    return lines


def normalize_deepstream_preferred_objects(value) -> list[str]:
    if isinstance(value, str):
        raw_items = re.split(r"[\n,]+", value)
    elif isinstance(value, list):
        raw_items = value
    else:
        raw_items = DEFAULT_DEEPSTREAM_SETTINGS["preferred_objects"]
    preferred = []
    seen = set()
    for item in raw_items:
        label = " ".join(str(item or "").strip().lower().replace("_", " ").split())[:48].rstrip()
        if not label or label in seen:
            continue
        seen.add(label)
        preferred.append(label)
        if len(preferred) >= 64:
            break
    return preferred


def deepstream_focus_target(objects: list[dict], source: str, preferred_objects=None) -> dict:
    source_key = str(source or "").strip().lower()
    if source_key not in {"wifi", "bulb"}:
        return {}
    candidates = [
        item
        for item in objects
        if isinstance(item, dict) and deepstream_object_label(item)
    ]
    if not candidates:
        return {}
    preferred = normalize_deepstream_preferred_objects(preferred_objects)
    target = None
    preferred_rank = None
    for rank, preferred_label in enumerate(preferred):
        matches = [
            item
            for item in candidates
            if deepstream_object_label(item).strip().lower() == preferred_label
        ]
        if matches:
            target = max(matches, key=deepstream_object_probability)
            preferred_rank = rank
            break
    if target is None:
        return {}
    return {
        "source": source_key,
        "target": deepstream_object_label(target),
        "probability": deepstream_object_probability(target),
        "preferred": preferred_rank is not None,
        "preferred_rank": preferred_rank,
    }


def start_deepstream_focus_request(
    command_path: Path | str,
    focus_target: dict,
    *,
    wake_socket: Path | str = "",
    timeout_seconds: float = 180.0,
    now: float | None = None,
) -> dict:
    """Start deterministic camera focus before slower notification rendering."""
    source = str(focus_target.get("source") or "").strip().lower()
    target = " ".join(str(focus_target.get("target") or "").strip().lower().split())
    if source not in {"wifi", "bulb"} or not target:
        return {}
    requested_at = time.time() if now is None else float(now)
    timeout = max(2.0, min(300.0, float(timeout_seconds or 180.0)))
    request = {
        "enabled": True,
        "source": source,
        "target_label": target,
        "requested_at": requested_at,
        "requested_monotonic_ns": time.monotonic_ns(),
        "expires_at": requested_at + timeout,
        "request_id": f"focus_{time.time_ns()}",
        "trigger": "deepstream_yolo_coco",
    }
    try:
        preferred_rank = int(focus_target.get("preferred_rank"))
    except (TypeError, ValueError):
        preferred_rank = -1
    if preferred_rank >= 0:
        request["preferred_rank"] = preferred_rank
        request["priority"] = preferred_rank + 1
    command_file = Path(command_path)
    lock_path = command_file.with_suffix(command_file.suffix + ".lock")
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    with lock_path.open("a+", encoding="utf-8") as lock_file:
        fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX)
        current = read_json_file(command_file, {})
        if current.get("enabled"):
            return current
        write_json_file(command_file, request)
    wake_path = str(wake_socket or "").strip()
    if wake_path:
        client = socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM)
        try:
            client.sendto(request["request_id"].encode("utf-8"), wake_path)
        except OSError:
            # The JSON command remains the durable polling fallback while the
            # controller is starting or being restarted.
            pass
        finally:
            client.close()
    return request


def deepstream_nemotron_event_prompt(
    source: str,
    change_text: str,
    objects: list[dict],
    preferred_objects=None,
    allow_focus: bool = True,
) -> tuple[str, dict]:
    source_key = str(source or "").strip().lower()
    focus_target = deepstream_focus_target(objects, source_key, preferred_objects) if allow_focus else {}
    if focus_target:
        action_lines = [
            (
                f'Before summarizing, focus on the {focus_target["target"]} using the focus_object tool '
                f'with source "{focus_target["source"]}".'
            ),
            "Wait for the tool result, then summarize the object-change event and that result.",
        ]
    else:
        action_lines = ["Summarize the object-change event; no focus tool call is required."]
    prompt = "\n".join(
        [
            f"Live Stream Processor object-change event from {camera_input_label_for_prompt(source_key)}.",
            f"Change: {change_text}.",
            "Detected objects and probabilities:",
            *deepstream_objects_prompt_lines(objects),
            "",
            *action_lines,
            "Use the attached boxed frame and object data when preparing the summary.",
        ]
    )
    return prompt, focus_target


def deepstream_sources_for_monitor(payload: dict, source: str = "") -> dict[str, dict]:
    wanted = str(source or "").strip().lower()
    sources = payload.get("sources") if isinstance(payload.get("sources"), dict) else {}
    if wanted and isinstance(sources.get(wanted), dict):
        return {wanted: sources[wanted]}
    if wanted:
        payload_source = str(payload.get("source") or wanted).strip().lower()
        if not payload_source or payload_source == wanted:
            return {wanted: {**payload, "source": wanted}}
        return {}
    if sources:
        return {
            str(key or value.get("source") or "").strip().lower(): value
            for key, value in sources.items()
            if isinstance(value, dict) and str(key or value.get("source") or "").strip()
        }
    payload_source = str(payload.get("source") or "wifi").strip().lower()
    return {payload_source: {**payload, "source": payload_source}}


def camera_input_label_for_prompt(source: str) -> str:
    source_key = str(source or "").strip().lower()
    labels = {
        "server": "server USB camera",
        "wifi": "Wi-Fi camera",
        "bulb": "light bulb camera",
        "browser": "browser camera",
    }
    return labels.get(source_key, source_key or "camera")


def clear_browser_audio_queue_files(args: argparse.Namespace) -> int:
    audio_dir = Path(args.browser_audio_dir)
    deleted = 0
    if audio_dir.exists():
        for audio_path in audio_dir.glob("browser_audio_*"):
            if not audio_path.is_file():
                continue
            try:
                audio_path.unlink()
                deleted += 1
            except FileNotFoundError:
                pass
        metadata_dir = audio_dir / "metadata"
        if metadata_dir.exists():
            for metadata_path in metadata_dir.glob("*.json"):
                if not metadata_path.is_file():
                    continue
                try:
                    metadata_path.unlink()
                except FileNotFoundError:
                    pass
    return deleted


def clear_transcript_after_audio_clear(args: argparse.Namespace, cleared_at: float) -> None:
    transcript_path = Path(args.transcript_path)
    data = read_json_file(transcript_path, {})
    sources = data.get("sources") if isinstance(data.get("sources"), dict) else {}
    fallback_stages: dict[str, list[dict]] = {}
    for source, source_state in sources.items():
        if not isinstance(source_state, dict):
            continue
        source_label = {
            "browser": "Browser microphone",
            "server": "Server microphone",
            "wifi": "Wi-Fi camera microphone",
            "bulb": "Light bulb camera microphone",
        }.get(source, f"{source.title()} microphone")
        fallback_stages[source] = [
            {
                "id": "capture",
                "title": f"{source_label} Audio Capture",
                "status": "waiting",
                "message": "Incoming audio buffers were cleared.",
                "updated_at": cleared_at,
            },
            {
                "id": "asr",
                "title": "Nemotron Speech Understanding (nemotron-speech-streaming-en-0.6b.nemo)",
                "status": "waiting",
                "message": "Waiting for fresh audio after buffer clear.",
                "payload": {"model": "nemotron-speech-streaming-en-0.6b.nemo"},
                "updated_at": cleared_at,
            },
            {
                "id": "publish",
                "title": "Transcript Publish",
                "status": "waiting",
                "message": "Transcript backlog was cleared.",
                "updated_at": cleared_at,
            },
        ]
        source_state["status"] = "waiting"
        source_state["message"] = "Incoming audio buffers cleared. Waiting for new audio."
        source_state["latest_text"] = ""
        source_state["latest_text_at"] = 0
        source_state["segment_count"] = 0
        source_state["stages"] = fallback_stages[source]
        source_state["updated_at"] = cleared_at
    payload = {
        **data,
        "status": "waiting",
        "message": "Incoming audio buffers cleared. Waiting for new audio.",
        "latest_text": "",
        "text": "",
        "segments": [],
        "stages": fallback_stages.get("browser") or fallback_stages.get("server") or [],
        "sources": sources,
        "audio_buffers_cleared_at": cleared_at,
        "updated_at": cleared_at,
    }
    write_json_file(transcript_path, payload)


def clear_browser_audio_buffers(
    args: argparse.Namespace,
    reason: str,
    *,
    preserve_session: bool = False,
) -> dict:
    audio_dir = Path(args.browser_audio_dir)
    deleted = 0
    if audio_dir.exists():
        for audio_path in audio_dir.glob("browser_audio_*"):
            if not audio_path.is_file():
                continue
            try:
                audio_path.unlink()
                deleted += 1
            except FileNotFoundError:
                pass
        metadata_dir = audio_dir / "metadata"
        if metadata_dir.exists():
            for metadata_path in metadata_dir.glob("*.json"):
                if not metadata_path.is_file():
                    continue
                try:
                    metadata_path.unlink()
                except FileNotFoundError:
                    pass
    now = time.time()
    control_payload = {
        "status": "cleared",
        "clear_requested_at": now,
        "deleted_browser_audio_files": deleted,
        "reason": reason,
        "message": "Incoming browser audio buffers were cleared.",
    }
    write_json_file(Path(args.audio_buffer_control_path), control_payload)
    if preserve_session:
        return control_payload

    session_id = f"audio-clear-{int(now * 1000)}"
    output_target = safe_voice_output_target(args)
    voice_payload, voicechat_payload = voice_session_payloads(args, now, session_id, output_target)
    if reason not in {"session_flush", "voice_response_clear"}:
        voicechat_payload = merge_voicechat_history_payload(
            voicechat_payload,
            read_json_file(voicechat_history_path(Path(args.voicechat_response_path)), {}),
        )
    reset_payload = {"session_id": session_id, "updated_at": now, "cleared_at": now, "reason": reason}
    write_json_file(Path(args.voice_session_reset_path), reset_payload)
    write_json_file(Path(args.voice_response_path), voice_payload)
    write_json_file(Path(args.voicechat_response_path), voicechat_payload)
    write_json_file(
        Path(args.speech_playback_lock_path),
        {
            "active": False,
            "audio_id": "",
            "cooldown_until": 0,
            "expires_at": 0,
            "message": "Audio buffer clear reset speech playback lock.",
            "phase": "cleared",
            "source": "",
            "updated_at": now,
        },
    )
    clear_transcript_after_audio_clear(args, now)
    return {**control_payload, "session_id": session_id}


def safe_voice_output_target(args: argparse.Namespace) -> str:
    output_target = read_json_file(Path(args.voice_output_target_path), {"target": "browser"}).get("target", "browser")
    if output_target not in {"browser", "server", "wifi_camera", "bulb_camera"}:
        return "browser"
    return str(output_target)


