        def receive_current_time_skill_settings(self) -> None:
            length_header = self.headers.get("Content-Length")
            try:
                length = int(length_header or "0")
            except ValueError:
                self.send_error(HTTPStatus.LENGTH_REQUIRED, "Invalid Content-Length")
                return
            if length <= 0 or length > 4096:
                self.send_error(HTTPStatus.BAD_REQUEST, "Invalid Current Time skill settings payload")
                return
            try:
                raw = json.loads(self.rfile.read(length).decode("utf-8"))
                if not isinstance(raw, dict):
                    raise ValueError("Current Time skill settings must be a JSON object")
                current = read_current_time_skill_settings(args)
                previous_sources = set(current.get("sources") or [])
                payload = write_current_time_skill_settings(args, {
                    **current,
                    **{key: raw[key] for key in ("enabled", "sources") if key in raw},
                })
                added_sources = set(payload.get("sources") or []) - previous_sources
                if added_sources:
                    now = time.time()
                    payload = write_current_time_skill_settings(args, {
                        **payload,
                        "next_publish_by_source": {
                            **payload.get("next_publish_by_source", {}),
                            **{source: draw_current_time_skill_next_at(now) for source in added_sources},
                        },
                    })
                if bool(raw.get("publish_now")):
                    payload = publish_current_time_skill(args, payload)
            except Exception as exc:
                self.send_error(HTTPStatus.BAD_REQUEST, str(exc))
                return
            self.send_json_payload(payload)

