        def send_agent_state(self, source: str = "") -> None:
            if not bool(getattr(args, "enable_environment_agents", False)):
                self.send_json_file(
                    Path(args.agent_state_path).with_suffix(".environment-agents-disabled.json"),
                    {
                        "status": "disabled",
                        "updated_at": time.time(),
                        "risk": "none",
                        "source_id": source or "unknown",
                        "message": "Environment agents are disabled while the stack is being redesigned.",
                    }
                )
                return
            path = Path(args.agent_state_path)
            if source == "server":
                path = Path(args.server_agent_state_path)
            elif source == "wifi":
                path = Path(args.wifi_agent_state_path)
            elif source == "bulb":
                path = Path(args.bulb_agent_state_path)
            elif source == "browser":
                path = Path(args.browser_agent_state_path)
            if source == "server" and not path.exists():
                path = Path(args.agent_state_path)
            self.send_json_file(
                path,
                {
                    "status": "waiting",
                    "updated_at": time.time(),
                    "risk": "none",
                    "message": "Environment agents are disabled while the stack is being redesigned.",
                },
            )

