        def default_deepstream_detections(self, source: str = "") -> dict:
            base = {
                **DEFAULT_DEEPSTREAM_DETECTIONS,
                "detections_path": str(Path(args.deepstream_detections_path)),
            }
            source_key = str(source or "").strip().lower()
            lane_ids = ("server", "wifi", "bulb", "browser")
            if source_key:
                return {
                    **base,
                    "source": source_key,
                    "message": f"Waiting for live stream processor detections for {source_key}.",
                }
            return {
                **base,
                "sources": {
                    lane_id: {
                        **base,
                        "source": lane_id,
                        "message": f"Waiting for live stream processor detections for {lane_id}.",
                    }
                    for lane_id in lane_ids
                },
            }

        def send_deepstream_detections(self, source: str = "") -> None:
            path = Path(args.deepstream_detections_path)
            source_key = str(source or "").strip().lower()
            if source_key and source_key not in {"server", "wifi", "bulb", "browser"}:
                self.send_error(HTTPStatus.BAD_REQUEST, "Invalid live stream processor detection source")
                return
            try:
                if path.exists():
                    payload = json.loads(path.read_text(encoding="utf-8"))
                    if not isinstance(payload, dict):
                        raise ValueError("Live stream processor detections payload must be a JSON object")
                else:
                    payload = self.default_deepstream_detections()
            except Exception as exc:
                self.send_json_payload(
                    {
                        "status": "error",
                        "error": f"Could not read live stream processor detections file: {exc}",
                        "message": "Live stream processor detection output is unavailable.",
                        "detections_path": str(path),
                    },
                    status=HTTPStatus.INTERNAL_SERVER_ERROR,
                )
                return

            payload = {
                **DEFAULT_DEEPSTREAM_DETECTIONS,
                **payload,
                "detections_path": str(path),
            }
            settings = self.read_deepstream_settings_payload()
            sources = payload.get("sources") if isinstance(payload.get("sources"), dict) else {}
            if sources:
                normalized_sources = {}
                for lane_id, lane_payload in sources.items():
                    if not isinstance(lane_payload, dict):
                        continue
                    lane_key = str(lane_id or lane_payload.get("source") or "").strip().lower()
                    if not lane_key:
                        continue
                    normalized_sources[lane_key] = deepstream_filter_payload_objects(
                        {
                            **payload,
                            **lane_payload,
                            "source": lane_key,
                            "sources": {},
                            "detections_path": str(path),
                        },
                        settings,
                    )
                payload["sources"] = normalized_sources
            else:
                payload = deepstream_filter_payload_objects(payload, settings)
            payload["deepstream_settings"] = settings

            self.maybe_queue_deepstream_nemotron_events(payload, source_key)

            if source_key:
                source_payload = payload.get("sources", {}).get(source_key)
                if isinstance(source_payload, dict):
                    self.send_json_payload(source_payload)
                    return
                payload_source = str(payload.get("source") or "").strip().lower()
                if not payload_source or payload_source == source_key:
                    self.send_json_payload({**payload, "source": source_key})
                    return
                self.send_json_payload(self.default_deepstream_detections(source_key))
                return

            self.send_json_payload(payload)

        def send_voice_output_target(self) -> None:
            self.send_json_file(
                Path(args.voice_output_target_path),
                {
                    "target": "browser",
                    "updated_at": time.time(),
                },
            )

        def send_voice_response_audio(self) -> None:
            response_path = Path(args.voice_response_path)
            try:
                data = json.loads(response_path.read_text(encoding="utf-8"))
                audio_path = Path(str(data.get("audio_path") or ""))
            except Exception:
                self.send_error(HTTPStatus.NOT_FOUND, "No voice response audio is available yet")
                return
            if not audio_path.exists() or not audio_path.is_file():
                self.send_error(HTTPStatus.NOT_FOUND, "No voice response audio is available yet")
                return
            payload = audio_path.read_bytes()
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "audio/wav")
            self.send_header("Content-Length", str(len(payload)))
            self.no_cache_headers()
            self.end_headers()
            self.wfile.write(payload)

        def send_voicechat_response_audio(self, parsed) -> None:
            audio_id = parse_qs(parsed.query).get("audio_id", [""])[0]
            if audio_id:
                safe_id = safe_audio_file_name(audio_id)
                if not safe_id:
                    self.send_error(HTTPStatus.BAD_REQUEST, "Invalid VoiceChat audio id")
                    return
                file_names = [safe_id] if safe_id.endswith(".wav") else [
                    f"{safe_id}.wav",
                    f"voice_{safe_id}_playback.wav",
                    f"voice_{safe_id}.wav",
                    f"voice_{safe_id}_capped.wav",
                    f"voice_{safe_id}_trimmed.wav",
                ]
                audio_path = next(
                    (
                        voicechat_audio_dir(args) / file_name
                        for file_name in file_names
                        if (voicechat_audio_dir(args) / file_name).exists()
                        and (voicechat_audio_dir(args) / file_name).is_file()
                    ),
                    None,
                )
                if audio_path is None:
                    self.send_error(HTTPStatus.NOT_FOUND, "No VoiceChat response audio is available for that id")
                    return
                payload = audio_path.read_bytes()
                self.send_response(HTTPStatus.OK)
                self.send_header("Content-Type", "audio/wav")
                self.send_header("Content-Length", str(len(payload)))
                self.no_cache_headers()
                self.end_headers()
                self.wfile.write(payload)
                return
            response_path = Path(args.voicechat_response_path)
            try:
                data = json.loads(response_path.read_text(encoding="utf-8"))
                audio_path = Path(str(data.get("audio_path") or ""))
            except Exception:
                self.send_error(HTTPStatus.NOT_FOUND, "No VoiceChat response audio is available yet")
                return
            if not audio_path.exists() or not audio_path.is_file():
                self.send_error(HTTPStatus.NOT_FOUND, "No VoiceChat response audio is available yet")
                return
            payload = audio_path.read_bytes()
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "audio/wav")
            self.send_header("Content-Length", str(len(payload)))
            self.no_cache_headers()
            self.end_headers()
            self.wfile.write(payload)

        def send_voicechat_cue_audio(self, parsed) -> None:
            stage = parse_qs(parsed.query).get("stage", [""])[0]
            safe_stage = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(stage or "")).strip("_")
            if not safe_stage:
                self.send_error(HTTPStatus.BAD_REQUEST, "Invalid VoiceChat cue stage")
                return
            cue_path = voicechat_stage_cue_path(args, safe_stage)
            if cue_path is None or not cue_path.exists() or not cue_path.is_file():
                self.send_error(HTTPStatus.NOT_FOUND, "VoiceChat cue audio is not available for that stage")
                return
            self.send_audio_file(cue_path, "audio/wav", "VoiceChat cue audio is not available")

        def send_audio_file(self, path: Path, content_type: str, missing_message: str) -> None:
            if not path.exists() or not path.is_file():
                self.send_error(HTTPStatus.NOT_FOUND, missing_message)
                return
            payload = path.read_bytes()
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(payload)))
            self.no_cache_headers()
            self.end_headers()
            self.wfile.write(payload)

        def send_voicechat_boundary_chunk(self, chunk_id: str) -> None:
            safe_id = safe_audio_file_name(chunk_id)
            if not safe_id:
                self.send_error(HTTPStatus.BAD_REQUEST, "Invalid boundary chunk id")
                return
            if safe_id.endswith(".wav"):
                file_name = safe_id
                safe_id = safe_id[:-4]
            else:
                file_name = f"{safe_id}.wav"
            if not safe_id.startswith("boundary_chunk_"):
                self.send_error(HTTPStatus.BAD_REQUEST, "Invalid boundary chunk id")
                return
            path = voicechat_audio_dir(args) / file_name
            self.send_audio_file(path, "audio/wav", "Boundary chunk audio is no longer available")

        def send_voicechat_tool_snapshot(self, snapshot_id: str) -> None:
            safe_name = safe_audio_file_name(snapshot_id)
            if (
                not safe_name
                or not re.fullmatch(r"(?:server|browser|wifi|bulb)_snapshot_[0-9]+\.(?:jpg|png)", safe_name)
            ):
                self.send_error(HTTPStatus.BAD_REQUEST, "Invalid VoiceChat tool snapshot id")
                return
            path = voicechat_audio_dir(args) / "tool-snapshots" / safe_name
            content_type = "image/png" if path.suffix.lower() == ".png" else "image/jpeg"
            self.send_static_file(path, content_type, 86400)

        def send_voicechat_tool_clip(self, clip_id: str) -> None:
            safe_name = safe_audio_file_name(clip_id)
            if not safe_name or not re.fullmatch(r"(?:server|wifi|bulb)_clip_[0-9]+\.mp4", safe_name):
                self.send_error(HTTPStatus.BAD_REQUEST, "Invalid VoiceChat tool clip id")
                return
            path = voicechat_audio_dir(args) / "tool-clips" / safe_name
            self.send_static_file(path, "video/mp4", 86400)

        def send_environment_scan_latest(self, parsed) -> None:
            query = parse_qs(parsed.query)
            source = re.sub(r"[^a-z0-9_-]+", "", str(query.get("source", ["wifi"])[0] or "wifi").strip().lower())
            if source not in {"wifi", "bulb"}:
                self.send_error(HTTPStatus.BAD_REQUEST, "Invalid environment scan source")
                return
            requested_file = Path(str(query.get("file", [""])[0] or "").strip()).name
            cacheable = str(query.get("cache", [""])[0] or "").strip().lower() in {"1", "true", "yes"}
            try:
                started_at = float(query.get("started_at", ["0"])[0] or 0)
            except (TypeError, ValueError):
                started_at = 0.0
            scan_dir = Path(args.environment_scan_output_dir).expanduser()
            if not scan_dir.exists() or not scan_dir.is_dir():
                self.send_error(HTTPStatus.NOT_FOUND, "No environment scan output is available yet")
                return
            if requested_file:
                if (
                    not requested_file.startswith(f"{source}_environment_scan_")
                    or not requested_file.endswith(".jpg")
                    or "/" in requested_file
                    or "\\" in requested_file
                ):
                    self.send_error(HTTPStatus.BAD_REQUEST, "Invalid environment scan file")
                    return
                requested_path = scan_dir / requested_file
                if not requested_path.exists() or not requested_path.is_file():
                    self.send_error(HTTPStatus.NOT_FOUND, "Environment scan image is no longer available")
                    return
                self.send_static_file(requested_path, "image/jpeg", 86400 if cacheable else 0)
                return

            def scan_image_candidates(require_started_at: bool) -> list[tuple[float, int, Path]]:
                candidates = []
                seen: set[Path] = set()
                for pattern in (f"{source}_environment_scan_*_preview.jpg", f"{source}_environment_scan_*.jpg"):
                    for path in scan_dir.glob(pattern):
                        if path in seen:
                            continue
                        seen.add(path)
                        try:
                            stat = path.stat()
                        except OSError:
                            continue
                        if not path.is_file():
                            continue
                        if require_started_at and started_at > 0 and stat.st_mtime < started_at - 1.5:
                            continue
                        is_preview = 1 if path.name.endswith("_preview.jpg") else 0
                        candidates.append((stat.st_mtime, is_preview, path))
                return candidates

            candidates = scan_image_candidates(True)
            if not candidates and started_at > 0:
                candidates = scan_image_candidates(False)
            if not candidates:
                self.send_error(HTTPStatus.NOT_FOUND, "No environment scan image is available yet")
                return
            _mtime, _is_preview, latest_path = max(candidates, key=lambda item: (item[0], item[1]))
            self.send_static_file(latest_path, "image/jpeg", 86400 if cacheable else 0)

        def send_browser_audio_chunk(self, name: str) -> None:
            safe_name = safe_audio_file_name(name)
            if not safe_name:
                self.send_error(HTTPStatus.BAD_REQUEST, "Invalid browser audio chunk name")
                return
            candidates: list[Path] = []
            if safe_name.startswith("browser_debug_"):
                candidates.append(browser_debug_audio_dir(args) / safe_name)
            if safe_name.startswith("browser_audio_"):
                candidates.append(Path(args.browser_audio_dir) / safe_name)
            if not candidates or Path(safe_name).suffix.lower() not in TRANSCRIBABLE_BROWSER_SUFFIXES:
                self.send_error(HTTPStatus.BAD_REQUEST, "Invalid browser audio chunk name")
                return
            for path in candidates:
                if path.exists() and path.is_file():
                    self.send_audio_file(path, audio_content_type(path), "Browser audio chunk is no longer available")
                    return
            self.send_error(HTTPStatus.NOT_FOUND, "Browser audio chunk is no longer available")

