            bulb_status = frame_store_status(bulb_store)
            bulb_audio_status = bulb_audio_store.status() if bulb_audio_store is not None else {}
            bulb_recovery = bulb_recovery_state.snapshot() if bulb_recovery_state is not None else {}
            audio_dir = Path(args.browser_audio_dir)
            latest_browser_audio = None
            browser_audio_queue = {
                "count": 0,
                "fresh_count": 0,
                "stale_count": 0,
                "max_age_seconds": args.browser_audio_max_age,
                "oldest_age_seconds": None,
                "newest_age_seconds": None,
                "chunks": [],
            }
            if audio_dir.exists():
                pruned_stale_count = prune_browser_audio_dir(
                    audio_dir,
                    keep=args.browser_audio_keep,
                    max_age_seconds=args.browser_audio_max_age,
                )
                browser_audio_queue["pruned_stale_count"] = pruned_stale_count
                now = time.time()
                chunk_infos = []
                for chunk_path in audio_dir.glob("browser_audio_*"):
                    if not chunk_path.is_file() or chunk_path.suffix.lower() not in TRANSCRIBABLE_BROWSER_SUFFIXES:
                        continue
                    try:
                        chunk_info = browser_audio_chunk_info(chunk_path, args, now)
                    except FileNotFoundError:
                        continue
                    chunk_infos.append(chunk_info)
                chunk_infos.sort(key=lambda item: item["modified_at"])
                browser_audio_queue["count"] = len(chunk_infos)
                browser_audio_queue["fresh_count"] = sum(1 for item in chunk_infos if item["fresh"])
                browser_audio_queue["stale_count"] = browser_audio_queue["count"] - browser_audio_queue["fresh_count"]
                if chunk_infos:
                    browser_audio_queue["oldest_age_seconds"] = chunk_infos[0]["age_seconds"]
                    browser_audio_queue["newest_age_seconds"] = chunk_infos[-1]["age_seconds"]
                    browser_audio_queue["chunks"] = chunk_infos[-24:]
